import React, { useState } from 'react';
import Slider from "react-slick"; // Make sure to install react-slick and slick-carousel

// Import slick-carousel styles
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function EventsSlider() {
  const [hovered, setHovered] = useState(false);

  const ArrowButton = ({ direction, onClick }) => {
    return (
      <div
        onClick={onClick}
        style={{
          position: "absolute",
          top: "50%",
          [direction]: "-50px",
          transform: "translateY(-50%)",
          backgroundColor: "#FFFF",
          borderRadius: "50%",
          width: "40px",
          height: "40px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          cursor: "pointer",
          zIndex: 10,
          boxShadow: "0 4px 8px rgba(0, 0, 0, 0.2)",
        }}
      >
        <span style={{ color: "#00b666", fontSize: "20px" }}>
          {direction === "left" ? "<" : ">"}
        </span>
      </div>
    );
  };

  const settings = {
    dots: true,
    arrows: true,
    infinite: true,
    autoplay: true,
    autoplaySpeed: 5000,
    slidesToShow: 1,
    slidesToScroll: 1,
    nextArrow: <ArrowButton direction="right" />,
    prevArrow: <ArrowButton direction="left" />,
  };

  return (
    <div style={styles.wrapper}>
      {/* Ek görseller */}
      <div style={styles.shapeDots}>
        <img
          src="assets/shape-dots.svg"
          alt="Dots Shape"
          style={{ width: "50px", height: "50px", marginLeft: "330px" }}
        />
      </div>
      <div style={styles.kesikCizgi}>
        <img
          src="assets/kesik-yan-cizgi.svg"
          alt="Kesik Çizgi"
          style={{ width: "142px", height: "142px", marginRight: "250px" }}
        />
      </div>

      {/* Slider */}
      <div style={styles.content}>
        <Slider {...settings} style={styles.slider}>
          {[1, 2, 3].map((_, index) => (
            <div
              key={index}
              style={{
                ...styles.contentBox,
                ...(hovered ? styles.contentBoxHover : {}),
              }}
              onMouseEnter={() => setHovered(true)}
              onMouseLeave={() => setHovered(false)}
            >
              <img
                src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
                alt={`Slide ${index + 1}`}
                style={styles.image}
              />
            </div>
          ))}
        </Slider>
      </div>

      {/* Alt Mavi Bar */}
      <div style={styles.bottomBar}></div>
    </div>
  );
}

const styles = {
  wrapper: {
    position: "relative",
    width: "100vw",
    margin: "0 auto",
    backgroundColor: "rgb(246, 248, 255)",
    overflow: "hidden",
  },
  shapeDots: {
    position: "absolute",
    top: "20px",
    left: "2px",
    zIndex: 5,
  },
  kesikCizgi: {
    position: "absolute",
    top: "20px",
    right: "20px",
    zIndex: 5,
  },
  content: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    margin: "0",
    position: "relative",
    opacity: "0.8",
  },
  slider: {
    width: "100%",
    maxWidth: "1200px",
    margin: "0 auto",
  },
  contentBox: {
    width: "100%",
    height: "400px",
    margin: "0",
    padding: "20px",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    border: "2px solid #e0e0e0",
    borderRadius: "12px",
    boxShadow: "4px 4px 0px 2px rgba(0, 182, 102, 0.6)",
    backgroundColor: "#fff",
    transition: "transform 0.3s ease-in-out",
    cursor: "pointer",
  },
  contentBoxHover: {
    transform: "translateY(-5px)",
    boxShadow: "8px 8px 0px 3px rgba(0, 182, 102, 0.8)",
  },
  image: {
    width: "auto",
    maxHeight: "100%",
    objectFit: "contain",
    borderRadius: "5px",
    boxShadow: "0 4px 8px rgba(0, 0, 0, 0.2)",
  },
  bottomBar: {
    width: "100%",
    height: "100px",
    backgroundColor: "#293349",
    marginTop: "5px",
  },
};

export default EventsSlider;
